Aquí está una función en C++ que toma una referencia a un `std::string` que contiene texto con formato Markdown y devuelve un `std::string` que contiene texto con formato HTML:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <regex>

std::string markdown_to_html(const std::string& markdown) {
    std::stringstream html_stream;

    // Heading tags
    std::regex regex_header(R"(^#+(\s+)?(.+?)\s*$)", std::regex::icase);
    std::smatch match;

    while (std::regex_search(markdown, match, regex_header)) {
        std::string header_level = match[1].str();
        std::string header_text = match[2].str();

        std::string html_header;
        switch (header_level.length()) {
            case 1:
                html_header = "<h1>" + header_text + "</h1>";
                break;
            case 2:
                html_header = "<h2>" + header_text + "</h2>";
                break;
            case 3:
                html_header = "<h3>" + header_text + "</h3>";
                break;
            case 4:
                html_header = "<h4>" + header_text + "</h4>";
                break;
            case 5:
                html_header = "<h5>" + header_text + "</h5>";
                break;
            case 6:
                html_header = "<h6>" + header_text + "</h6>";
                break;
            default:
                html_header = "<h1>" + header_text + "</h1>";
                break;
        }

        html_stream << html_header;
        markdown.erase(match.position(), match.length());
    }

    // Bold and italic text
    std::regex regex_bold(R"(__(.+?)__)", std::regex::icase);
    std::regex regex_italic(R"(__(.+?)__)", std::regex::icase);
    std::regex regex_bold_italic(R"(__(.+?)__)", std::regex::icase);

    while (std::regex_search(markdown, match, regex_bold)) {
        std::string text = match[1].str();
        std::string html_bold = "<strong>" + text + "</strong>";
        html_stream << html_bold;
        markdown.erase(match.position(), match.length());
    }

    while (std::regex_search(markdown, match, regex_italic)) {
        std::string text = match[1].str();
        std::string html_italic = "<em>" + text + "</em>";
        html_stream << html_italic;
        markdown.erase(match.position(), match.length());
    }

    while (std::regex_search(markdown, match, regex_bold_italic)) {
        std::string text = match[1].str();
        std::string html_bold_italic = "<strong><em>" + text + "</em></strong>";
        html_stream << html_bold_italic;
        markdown.erase(match.position(), match.length());
    }

    // Links
    std::regex regex_link(R"((\[.+?\])(\(\S+\)))", std::regex::icase);
    while (std::regex_search(markdown, match, regex_link)) {
        std::string link_text = match[1].str();
        std::string link_url = match[2].str();

        std::string html_link = "<a href=\"" + link_url + "\">" + link_text + "</a>";
        html_stream << html_link;

        markdown.erase(match.position(), match.length());
    }

    // Lists
    std::regex regex_ordered_list(R"(^\d+\.\s(.+?)$)", std::regex::icase);
    std::regex regex_unordered_list(R"(^\*+\s(.+?)$)", std::regex::icase);

    while (std::regex_search(markdown, match, regex_ordered_list)) {
        std::string list_item = match[1].str();
        std::string html_ordered_list_item = "<li>" + list_item + "</li>";
        std::string html_ordered_list = "<ol><li>" + list_item + "</li></ol>";

        if (std::regex_search(list_item, std::regex(R"(^\d+\.)", std::regex::icase))) {
            html_stream << html_ordered_list;
        } else {
            html_stream << html_ordered_list_item;
        }

        markdown.erase(match.position(), match.length());
    }

    while (std::regex_search(markdown, match, regex_unordered_list)) {
        std::string list_item = match[1].str();
        std::string html_unordered_list_item = "<li>" + list_item + "</li>";
        std::string html_unordered_list = "<ul><li>" + list_item + "</li></ul>";

        if (std::regex_search(list_item, std::regex(R"(^\*\s)", std::regex::icase))) {
            html_stream << html_unordered_list;
        } else {
            html_stream << html_unordered_list_item;
        }

        markdown.erase(match.position(), match.length());
    }

    // Code blocks
    std::regex regex_code_block(R"(^(?:`{3,}|~{3,})\s*(.+?)\s*(?:`{3,}|~{3,})\n(?:(?:(?!```|~{3,}).)*|\n)+\n*)", std::regex::icase);
    while (std::regex_search(markdown, match, regex_code_block)) {
        std::string code = match[1].str();
        std::string html_code_block = "<pre><code>" + code + "</code></pre>";

        html_stream << html_code_block;

        markdown.erase(match.position(), match.length());
    }

    // Paragraphs
    std::string html_paragraph;
    std::string current_line;
    while (!markdown.empty()) {
        std::size_t newline_pos = markdown.find('\n');
        if (newline_pos != std::string::npos) {
            current_line += markdown.substr(0, newline_pos);
            markdown.erase(0, newline_pos + 1);

            html_paragraph += current_line;
            html_stream << "<p>" << html_paragraph << "</p>";
            html_paragraph.clear();
            current_line.clear();
        } else {
            current_line += markdown.substr(0, markdown.length());
            markdown.clear();
            html_paragraph += current_line;
            html_stream << "<p>" << html_paragraph << "</p>";
            html_paragraph.clear();
            current_line.clear();
            break;
        }
    }

    return html_stream.str();
}

int main() {
    std::string markdown_text = "## Heading\n"
                                 "### Subheading\n"
                                 "\n"
                                 "This is some **bold** and *italic* text.\n"
                                 "\n"
                                 "[Google](https://www.google.com/)\n"
                                 "\n"
                                 "1. Item one\n"
                                 "2. Item two\n"
                                 "   - Subitem\n"
                                 "3. Item three\n"
                                 "\n"
                                 "* Unordered item 1\n"
                                 "  * Subitem 1\n"
                                 "  * Subitem 2\n"
                                 "* Unordered item 2\n"
                                 "\n"
                                 "`const int x = 42;`";

    std::string html_text = markdown_to_html(markdown_text);
    std::cout << html_text << std::endl;

    return 0;
}
```

Este código utiliza la biblioteca estándar de C++ `std::regex` para realizar las diferentes transformaciones de Markdown a HTML. El método `std::regex_search` se utiliza para encontrar las diferentes secciones de texto dentro del `std::string` de entrada, y se aplican los diferentes estilos HTML correspondientes. Los diferentes casos se manejan utilizando `if-else` y `switch` para elegir los tags HTML adecuados. Se incluye también el manejo de las listas ordenadas y desordenadas, los bloques de código, y los párrafos. Se prueba el código con un ejemplo de texto de entrada en el `main()` para mostrar el resultado.

