#include <fstream>
#include <string>
```

2. A continuación, define una función que lea el archivo de texto línea por línea y cuente el número de apariciones de la palabra específica:

```cpp
void countWordOccurrences(std::string filename, std::string word) {
    std::ifstream file(filename); // Abrir el archivo en modo lectura
    if (!file.is_open()) { // Verificar si se pudo abrir el archivo
        std::cerr << "Error: Unable to open file " << filename << std::endl;
        return;
    }

    std::string line;
    int count = 0;
    while (std::getline(file, line)) { // Leer línea por línea
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != std::string::npos) { // Buscar la palabra específica en la línea
            count++; // Incrementar el conteo si se encuentra la palabra
            pos++; // Avanzar el índice para buscar la siguiente aparición
        }
    }

    file.close(); // Cerrar el archivo

    std::cout << "The word '" << word << "' appears " << count << " times in " << filename << std::endl;
}
```

3. Ahora, puedes llamar a esta función pasando el nombre del archivo y la palabra específica como argumentos:

```cpp
int main() {
    std::string filename = "example.txt";
    std::string word = "hello";

    countWordOccurrences(filename, word);

    return 0;
}
```

